<?php
declare(strict_types=1); require_once __DIR__.'/../bootstrap.php'; Auth::requireRole('admin');
$pdo=db(); $q=trim((string)($_GET['q']??'')); $action=trim((string)($_GET['action']??''));
$where=[]; $args=[]; if($q!==''){ $where[]='(a.action LIKE ? OR a.entity_type LIKE ? OR CAST(a.entity_id AS CHAR) LIKE ? OR u.name LIKE ? OR u.email LIKE ?)'; $like='%'.$q.'%'; array_push($args,$like,$like,$like,$like,$like); } if($action!==''){ $where[]='a.action=?'; $args[]=$action; }
$sql='SELECT a.id,a.action,a.entity_type,a.entity_id,a.ip_address,a.created_at,a.old_values,a.new_values,u.name actor FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_user_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY a.id DESC LIMIT 500'; $st=$pdo->prepare($sql); $st->execute($args); $logs=$st->fetchAll();
$actions=$pdo->query('SELECT DISTINCT action FROM audit_logs ORDER BY action')->fetchAll(PDO::FETCH_COLUMN); $active='audit'; $pageTitle='Audit Logs'; $pageDescription='Security and administrative activity trail';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit Logs · DogoFlow Admin</title><link rel="stylesheet" href="<?=url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=url('/assets/css/admin.css')?>"><link rel="stylesheet" href="<?=url('/assets/css/admin-ui-consistency.css')?>"><link rel="stylesheet" href="<?=url('/assets/css/responsive.css')?>"></head><body class="admin-shell"><?php require __DIR__.'/../partials/admin_sidebar.php'; ?><section class="admin-main"><?php require __DIR__.'/../partials/admin_topbar.php'; ?><main class="admin-content"><div class="page-heading"><div><h1>Audit Logs</h1><p>Review recorded security and administrative changes.</p></div></div><article class="panel-df"><form method="get" class="admin-filter-row"><input class="checkout-input" type="search" name="q" value="<?=e($q)?>" placeholder="Search actor, action or record ID"><select class="checkout-input" name="action"><option value="">All actions</option><?php foreach($actions as $a):?><option value="<?=e($a)?>" <?=$action===$a?'selected':''?>><?=e(ucwords(str_replace('_',' ',$a)))?></option><?php endforeach;?></select><button class="btn-df primary" type="submit">Filter logs</button><a class="btn-df secondary" href="<?=url('/admin/audit-logs.php')?>">Reset</a></form><div class="table-wrap-df"><table class="table-df"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Entity</th><th>Details</th><th>IP</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=e(date('d M Y · H:i',strtotime((string)$l['created_at'])))?></td><td><?=e($l['actor']??'System / removed user')?></td><td><strong><?=e($l['action'])?></strong></td><td><?=e(($l['entity_type']??'').' #'.($l['entity_id']??''))?></td><td><details><summary>View</summary><small>Before: <?=e((string)($l['old_values']??'—'))?></small><br><small>After: <?=e((string)($l['new_values']??'—'))?></small></details></td><td><?=e((string)($l['ip_address']??'—'))?></td></tr><?php endforeach;if(!$logs):?><tr><td colspan="6"><div class="empty-df">No audit events match these filters. Events appear when audited actions are performed.</div></td></tr><?php endif;?></tbody></table></div></article></main></section></body></html>